const configs={
  chr2:{name:'ChR2',peak:470,width:28,sign:1,color:'#43d9ff',verb:'opens cation channels and depolarizes'},
  enphr:{name:'eNpHR3.0',peak:590,width:32,sign:-1,color:'#ffb13b',verb:'pumps chloride inward and hyperpolarizes'}
};
const specs=[
  {id:'wavelength',label:'Wavelength',unit:' nm',min:430,max:620,step:1,value:470},
  {id:'power',label:'Irradiance',unit:' mW/mm²',min:0,max:20,step:.1,value:8},
  {id:'duty',label:'Duty cycle',unit:'%',min:5,max:100,step:1,value:40},
  {id:'frequency',label:'Pulse frequency',unit:' Hz',min:1,max:100,step:1,value:20},
  {id:'expression',label:'Opsin expression',unit:'%',min:0,max:100,step:1,value:75}
];
const values=Object.fromEntries(specs.map(s=>[s.id,s.value]));
const controls=document.querySelector('#controls');
specs.forEach(s=>{const el=document.createElement('div');el.className='control';el.innerHTML=`<div class="control-head"><label for="${s.id}">${s.label}</label><output id="${s.id}Out">${s.value}${s.unit}</output></div><input id="${s.id}" type="range" min="${s.min}" max="${s.max}" step="${s.step}" value="${s.value}"><div class="range-row"><span>${s.min}${s.unit}</span><span>${s.max}${s.unit}</span></div>`;controls.append(el);el.querySelector('input').addEventListener('input',e=>{values[s.id]=+e.target.value;document.querySelector(`#${s.id}Out`).textContent=`${values[s.id]}${s.unit}`;document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('active'));update()})});
const opsin=document.querySelector('#opsin');
opsin.addEventListener('change',()=>{const c=configs[opsin.value];values.wavelength=c.peak;syncInputs();update()});
const presets={sub:{power:1,duty:10,frequency:5,expression:35},precise:{power:8,duty:40,frequency:20,expression:75},strong:{power:17,duty:80,frequency:60,expression:95}};
document.querySelectorAll('[data-preset]').forEach(btn=>btn.addEventListener('click',()=>{Object.assign(values,presets[btn.dataset.preset]);values.wavelength=configs[opsin.value].peak;syncInputs();document.querySelectorAll('[data-preset]').forEach(b=>b.classList.toggle('active',b===btn));update()}));
function syncInputs(){specs.forEach(s=>{document.querySelector(`#${s.id}`).value=values[s.id];document.querySelector(`#${s.id}Out`).textContent=`${values[s.id]}${s.unit}`})}
function sigmoid(x){return 1/(1+Math.exp(-x))}
let model={activation:0,drive:0,delta:0,response:0};
function calculate(){const c=configs[opsin.value];const eta=Math.exp(-.5*Math.pow((values.wavelength-c.peak)/c.width,2));const dose=(values.power/20)*(values.duty/100)*(values.expression/100);const frequencyGain=.7+.3*Math.min(values.frequency,50)/50;const raw=eta*dose*frequencyGain;const activation=Math.max(0,(sigmoid(11*(raw-.16))-.147)/.853);const drive=c.sign*activation;const delta=c.sign*activation*(15+45*Math.min(values.frequency,60)/60);return{eta,activation,drive,delta,response:activation*(.6+.4*values.expression/100)}}
function update(){model=calculate();const c=configs[opsin.value],pct=Math.round(model.activation*100);document.querySelector('#activation').textContent=pct;document.querySelector('#scoreRing').style.background=`conic-gradient(${c.color} ${pct}%,#e6e8ec ${pct}%)`;document.querySelector('#drive').textContent=(model.drive>=0?'+':'')+model.drive.toFixed(2);document.querySelector('#firing').textContent=(model.delta>=0?'+':'')+model.delta.toFixed(0)+' Hz';document.querySelector('#network').textContent=pct<18?'quiet':pct<55?'localized':'propagating';document.querySelector('#driveBar').style.width=pct+'%';document.querySelector('#firingBar').style.width=Math.min(100,Math.abs(model.delta)/60*100)+'%';document.querySelector('#networkBar').style.width=Math.round(model.response*100)+'%';document.querySelector('#beamLabel').textContent=values.wavelength+' nm';document.querySelector('#interpretation').textContent=`At ${values.wavelength} nm, spectral match is ${Math.round(model.eta*100)}%. ${c.name} ${c.verb} selected neurons, producing an estimated ${model.delta>=0?'increase':'decrease'} in firing.`;document.documentElement.style.setProperty('--sim-color',c.color)}

const canvas=document.querySelector('#neuralCanvas'),ctx=canvas.getContext('2d');let width=0,height=0,dpr=1,rotX=-.18,rotY=.55,zoom=1,paused=false,time=0,drag=false,lastX=0,lastY=0;
const neurons=Array.from({length:58},(_,i)=>{const r=90+Math.random()*125,a=Math.random()*Math.PI*2,z=(Math.random()-.5)*260;return{x:Math.cos(a)*r+(Math.random()-.5)*45,y:Math.sin(a)*r*.72+(Math.random()-.5)*40,z,selected:i%5===0,size:2+Math.random()*3,phase:Math.random()*6.28}});
const edges=[];neurons.forEach((n,i)=>{const nearest=neurons.map((m,j)=>({j,d:(n.x-m.x)**2+(n.y-m.y)**2+(n.z-m.z)**2})).filter(x=>x.j!==i).sort((a,b)=>a.d-b.d).slice(0,2);nearest.forEach(x=>{if(i<x.j)edges.push([i,x.j,Math.random()])})});
function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(2,devicePixelRatio||1);width=r.width;height=r.height;canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}new ResizeObserver(resize).observe(canvas);
function project(n){const cy=Math.cos(rotY),sy=Math.sin(rotY),cx=Math.cos(rotX),sx=Math.sin(rotX);let x=n.x*cy-n.z*sy,z=n.x*sy+n.z*cy,y=n.y*cx-z*sx;z=n.y*sx+z*cx;const p=520/(520+z);return{x:width/2+x*p*zoom,y:height/2+y*p*zoom,z,p}}
function frame(ts){if(!paused)time=ts*.001;ctx.clearRect(0,0,width,height);const pts=neurons.map(project);edges.forEach(([a,b,phase])=>{const p=pts[a],q=pts[b],alpha=.08+.12*Math.max(0,(p.p+q.p)/2);ctx.strokeStyle=`rgba(105,155,218,${alpha})`;ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();if(model.activation>.08){const t=(time*(.25+model.activation*1.8)+phase)%1,from=model.drive>=0?p:q,to=model.drive>=0?q:p;const x=from.x+(to.x-from.x)*t,y=from.y+(to.y-from.y)*t;ctx.fillStyle=configs[opsin.value].color;ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=10;ctx.beginPath();ctx.arc(x,y,1.5+model.activation*2,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}});pts.map((p,i)=>({...p,n:neurons[i]})).sort((a,b)=>b.z-a.z).forEach(p=>{const active=p.n.selected&&Math.sin(time*values.frequency*.16+p.n.phase)>.15-model.activation;const col=p.n.selected?configs[opsin.value].color:'#55749d';ctx.fillStyle=col;ctx.globalAlpha=p.n.selected?.72:.42;ctx.shadowColor=col;ctx.shadowBlur=active?18*model.activation:3;ctx.beginPath();ctx.arc(p.x,p.y,p.n.size*p.p*(active?1.8:1),0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.shadowBlur=0});requestAnimationFrame(frame)}requestAnimationFrame(frame);
canvas.addEventListener('pointerdown',e=>{drag=true;lastX=e.clientX;lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;rotY+=(e.clientX-lastX)*.008;rotX+=(e.clientY-lastY)*.008;lastX=e.clientX;lastY=e.clientY});canvas.addEventListener('pointerup',()=>drag=false);canvas.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(1.7,zoom-e.deltaY*.001))},{passive:false});document.querySelector('#resetView').addEventListener('click',()=>{rotX=-.18;rotY=.55;zoom=1});document.querySelector('#toggle').addEventListener('click',e=>{paused=!paused;e.target.textContent=paused?'Play':'Pause';e.target.setAttribute('aria-label',paused?'Play animation':'Pause animation')});
update();
